WITH base AS (SELECT * FROM store_sales WHERE revenue > 1500), store_sales_stats AS (SELECT CASE WHEN YEAR(sale_date) < 2024 THEN 'before_2024' WHEN YEAR(sale_date) = 2024 THEN '2024' ELSE 'after_2024' END AS sale_cohort, AVG(revenue) AS avg_revenue, COUNT(units) AS units_count FROM base GROUP BY CASE WHEN YEAR(sale_date) < 2024 THEN 'before_2024' WHEN YEAR(sale_date) = 2024 THEN '2024' ELSE 'after_2024' END) SELECT sale_cohort, avg_revenue, units_count FROM store_sales_stats ORDER BY units_count DESC;
